const items = $input.all();
const now = Date.now();

// SLA định mức thời gian xử lý tối đa theo phút:
const SLA_LIMITS = {
  'Critical': 30,    // 30 phút
  'High': 120,       // 2 tiếng
  'Medium': 480,     // 8 tiếng
  'Low': 1440        // 24 tiếng
};

const breachedTickets = [];

for (const item of items) {
  const ticket = item.json;
  const priority = ticket.priority || 'Medium';
  const limitMinutes = SLA_LIMITS[priority] || 480;
  const createdAt = ticket.createdAt ? new Date(ticket.createdAt).getTime() : now;
  const elapsedMinutes = Math.floor((now - createdAt) / (1000 * 60));

  // Kiểm tra nếu thời gian chờ vượt quá giới hạn SLA và chưa được cảnh báo trước đó
  if (elapsedMinutes >= limitMinutes && !ticket.escalated) {
    breachedTickets.push({
      ticketId: ticket.ticketId || 'TCK-UNKNOWN',
      title: ticket.title || 'Không có tiêu đề',
      priority: priority,
      assignedTeam: ticket.assignedTeam || 'IT General',
      elapsedMinutes: elapsedMinutes,
      allowedMinutes: limitMinutes,
      overdueBy: elapsedMinutes - limitMinutes
    });
  }
}

return {
  totalOpen: items.length,
  breachedCount: breachedTickets.length,
  breachedTickets,
  checkedAt: new Date().toISOString()
};

